/* ==========================================================================
   Carga de la Bitácora 2026-II (corte 2026-06-30) — dnp_dpip (.NET / SQL Server)
   Generado desde la instancia de referencia. UN SOLO LOTE TRANSACCIONAL (sin GO):
   si algo falla, revierte todo (SET XACT_ABORT ON). Re-ejecutable (idempotente).

   Ejecutar:
     sqlcmd -S <host,puerto> -d dnp_dpip -U <usuario> -P <clave> -b -i 2026-II_2026-06-30_carga.sql
     (o abrirlo en SSMS y ejecutar; NO requiere modo SQLCMD porque no usa GO)

   Efecto:
     - Si 2026-II ya existe, borra sus datos y la recrea.
     - Inserta metadatos + todas las secciones de 2026-II.
     - Reemplaza la Evolución PGN (pgn_concepto/pgn_ejecucion), que es GLOBAL
       (compartida por todas las bitácoras): pasará a reflejar el corte de junio.

   Nota de visualización: las secciones SGP y "sectores por región" no tienen
   fuente para este corte, por lo que quedan vacías para 2026-II. Para que se
   OCULTEN limpiamente (en vez de mostrar datos de ejemplo) la aplicación .NET
   debe tener el frontend actualizado; ver el README que acompaña este script.
   ========================================================================== */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

DECLARE @periodo nvarchar(20) = N'2026-II';
DECLARE @bid INT;

/* 1) Idempotencia: si ya existe, borrar sus datos (y luego recrear) */
SELECT @bid = id FROM dbo.metadatos_bitacora WHERE periodo = @periodo;
IF @bid IS NOT NULL
BEGIN
    DELETE FROM dbo.inversion_transformaciones WHERE bitacora_id = @bid;
    DELETE FROM dbo.inversion_componentes_pnd WHERE bitacora_id = @bid;
    DELETE FROM dbo.ejecucion_transformaciones WHERE bitacora_id = @bid;
    DELETE FROM dbo.apropiacion_por_sector WHERE bitacora_id = @bid;
    DELETE FROM dbo.compromisos_pct_por_sector WHERE bitacora_id = @bid;
    DELETE FROM dbo.obligaciones_pct_por_sector WHERE bitacora_id = @bid;
    DELETE FROM dbo.pagos_pct_por_sector WHERE bitacora_id = @bid;
    DELETE FROM dbo.ejecucion_historica WHERE bitacora_id = @bid;
    DELETE FROM dbo.ejecucion_sectorial_entidades WHERE bitacora_id = @bid;
    DELETE FROM dbo.ejecucion_sectorial_mensual WHERE bitacora_id = @bid;
    DELETE FROM dbo.regionalizacion WHERE bitacora_id = @bid;
    DELETE FROM dbo.regionalizacion_sectores WHERE bitacora_id = @bid;
    DELETE FROM dbo.vigencias_futuras WHERE bitacora_id = @bid;
    DELETE FROM dbo.deflactores_pib WHERE bitacora_id = @bid;
    DELETE FROM dbo.credito_portafolio WHERE bitacora_id = @bid;
    DELETE FROM dbo.credito_ejecucion_entidad WHERE bitacora_id = @bid;
    DELETE FROM dbo.credito_ejecucion_historica WHERE bitacora_id = @bid;
    DELETE FROM dbo.sgp_historico_participacion WHERE bitacora_id = @bid;
    DELETE FROM dbo.sgp_historico_componentes WHERE bitacora_id = @bid;
    DELETE FROM dbo.metadatos_bitacora WHERE id = @bid;
END

/* 2) Crear la bitácora y capturar el id asignado por IDENTITY */
INSERT INTO dbo.metadatos_bitacora (numero_bitacora, periodo, corte_fecha, fuente_principal, notas)
VALUES (N'4', @periodo, '2026-06-30', N'BASE DETALLE MENSUAL (Sec 1 aproximada por llave programática)', N'Sec 1 derivada de BASE — desglose por transformación aproximado.');
SET @bid = CAST(SCOPE_IDENTITY() AS INT);
PRINT 'Bitacora ' + @periodo + ' con id=' + CAST(@bid AS varchar(10));

/* 3) Datos por sección (bitacora_id = @bid) */

