/* 5) Verificación rápida (antes del COMMIT) */
SELECT periodo, corte_fecha, id AS bitacora_id FROM dbo.metadatos_bitacora WHERE periodo = @periodo;
SELECT 'inversion_transformaciones' AS tabla, COUNT(*) AS n FROM dbo.inversion_transformaciones WHERE bitacora_id=@bid
UNION ALL SELECT 'apropiacion_por_sector', COUNT(*) FROM dbo.apropiacion_por_sector WHERE bitacora_id=@bid
UNION ALL SELECT 'ejecucion_historica', COUNT(*) FROM dbo.ejecucion_historica WHERE bitacora_id=@bid
UNION ALL SELECT 'regionalizacion', COUNT(*) FROM dbo.regionalizacion WHERE bitacora_id=@bid
UNION ALL SELECT 'vigencias_futuras', COUNT(*) FROM dbo.vigencias_futuras WHERE bitacora_id=@bid
UNION ALL SELECT 'credito_portafolio', COUNT(*) FROM dbo.credito_portafolio WHERE bitacora_id=@bid
UNION ALL SELECT 'pgn_ejecucion (global)', COUNT(*) FROM dbo.pgn_ejecucion;

COMMIT;
PRINT 'Carga de la bitacora completada y confirmada (COMMIT).';
